import runpy,json
from pathlib import Path
S=Path(__file__).resolve().parents[1];e=runpy.run_path(str(S/'work/write_superdaily_early.py'));add=e['add'];out=e['out'];cost=e['cost']
add('五分日沖','開盤觀察一段分鐘區間，再按區間後第一根open相對日開盤決定一口方向，用區間距離倍數停損停利。','開盤區間與當沖',['每日必須先有開盤時間<=HHmm<開盤+進場分鐘的資料，取其第一根open與期間high/low。','第一根達進場分鐘且未到出場時刻只判一次：open>日開盤+多距離多，<日開盤−空距離空；兩者都不符當天放棄，不繼續等突破。'],['從下一根起僅以open檢查，停損優先再停利；多單距離單位=abs(進場價−觀察期最低)，空=abs(觀察期最高−進場價)。','第一根HHmm>=出場時間用open平；若缺此時窗，跨曆日第一根回填前根close平；末筆仍持倉按close平。','發現前根合約不同在當根一般處理之後，若尚有倉會回填前根close平，可能晚發現換約卻回填更早成交。'],[cost,'每曆日最多一次判定／一口，沒有加碼。CalcStopUnit只取價差絕對值，不讀ATR天數或ATR乘數，唯讀倍數單位也未實際分支。','不呼叫ValidKBAR，所謂5分由進場分鐘決定，不是固定聚合5分鐘K線。'],['缺開盤觀察區間就不初始化，也不補進；進場分鐘<=0可使狀態始終未開盤而不交易。','風控只看後續open，不按盤中high/low觸價，也不在進場同根查損益；距離0時下一根可能立即退出。','換約檢查在當根可能進場之後，退出時間能早於新進時間，讀績效需留意此時序。'],{'開盤時間':'HHmm觀察區間起點；需至少一根位於起點至進場時刻之前才初始化。','進場分鐘':'開盤起加此分鐘為單次判方向的最早時刻；不是觀察期後一直等待突破。','出場時間':'第一根>=此HHmm按open平；僅在此時刻之前才可入場。','多突破':'日首open加%或點數，進場判定open嚴格大於才多，0也不含等號。','空突破':'日首open減%或點數，進場判定open嚴格小於才空。','ATR天數':'此版核心未計ATR，CalcStopUnit只用進場與開盤區間極值價差，此欄不改交易。','ATR乘數':'核心未使用，沒有乘ATR轉風控距離。','停損倍數':'進場價上下以區間距離×此倍數設定，後續僅open到線退出，優先於停利。','停利倍數':'同一區間距離×此倍數為有利門檻，後續open觸發。'})
protect={'停損比':'入場價加減%或點數固定損；多open、空high判，實際用base退出所以open成交。','啟動移停比':'入場價加減有利距離，high/low達到後改啟移參考為當根open。','移停拉回比':'每次用當根open加減距離更新線，只判不同，沒有單向鎖線；當根close越線可退出但成交open。','直接停利比':'入場價加減距離；連黑版持倉第一順位就查，擠氣球版需已有移停線才查。','KBAR間隔ex':'只篩每根持倉價格風控，不篩日界選訊號、持有天數到期或末端強平。','開始交易時間':'ValidKBAR分鐘相位原點，沒有額外限制日界的下一根open新進。','策略方向':'同一套日型態與開盤條件可選做多或做空，不會因選空而反轉訊號條件。','持有天數':'新子項計0，每個曆日最後根先判已持有>=設定才退出，否則加一；0入場當日到期，1下一曆日到期，成交open非close。'}
add('連黑作多','用多日K棒區間、隔日跳空、MA及新高低延遲作條件，每日最多新增一口，持有至天數或價格風控出場。','日型態與反轉',['曆日末先從日K取當天資料，所有啟用條件且abs淨部位<最大口數，下一根open按策略方向新增一口。','K棒都要逐根檢查close−open在上下界內；總共卻把N根open−close加總再與同一上下界比，正負定義相反，並非必定逐日黑K。','可要求次日open−今日日close在區間、次日open相對含今日日收盤MA，再要求最新收盤嚴格破此前M收盤高／低後P日恰好相等才進。'],['KBAR通過先直接停利，再已有移停回撤，否則固定損；更新線時close也可即退，但全部策略停止走base，實際open成交。','每個子項依曆日計持有天數，到期用當日最後根open退出並移除；資料末筆全部用close退出。','換約逐子項一口平舊開新並按delta偏移所有正值風控線，再continue略過當根其他處理。'],[cost,'所有子項ID同1，先反序處理既有再判新倉，出掉後同個日界可釋放容量再新開。新高低延遲只在容量可用且其他條件已通過時更新參考。'],['總共模式與都要模式的紅黑符號相反；名稱連黑不保證每個設定都是連續黑棒。','新高低用收盤而非盤中high/low；Count−索引在突破當天為1，P=1就是該日收盤後下一根進，非再等完整一天。','日K找不到精確同日索引未防負值就取ds1d[idx]，缺日可出錯；MA樣本不足回0，上方條件可能放行而下方可能擋掉。'],protect|{'最大口數':'按目前abs淨持倉限制每日新增一口，不限制累計交易次數。','k棒條件':'無略過；都要逐根close−open在界內；總共改算N根open−close合計，在界內才過。','連續黑k天數':'都要／總共使用N個日K含今日；索引需>=N才開始，較首完整窗口晚一筆。','k棒需小於':'K值上界，超過才失敗，等號通過；模式不同符號不同。','k棒需大於':'K值下界，低於才失敗，等號通過；不是自動負值門檻。','開盤相對昨收':'需要則檢查次日open−當日日K close的固定點數區間，皆可略過。','相對昨收要小於':'開盤價差上界點數，含等號。','相對昨收要大於':'開盤價差下界點數，含等號。','進場相對MA':'以次日open>=或<=本次已收集收盤MA檢查；不足長度CalcMA回0。','X日MA':'從每個曆日末取得的日K close累積，含當日，未直接讀整段日K暖機。','高低點進場':'最新收盤嚴格突破此前M個收盤高／低，僅其他條件先通過且有容量才更新突破日期。','突破M日高低點':'以收盤而非日盤高低判前M樣本，等於舊高低不算突破。','突破後P日進場':'Count−突破索引恰等P才通過；突破當天值1，P=1即下一根open進。'})
add('擠氣球作多','日收盤在N日內漲跌達距離，且次日開盤符合價差條件就新增一口，可做多或做空並持有數日。','日型態與反轉',['曆日末取日收盤與N筆前收盤相比，上漲需>=前價+距離，下跌需<=前價−距離。','再檢查下一根open>=或<=今日收盤+開盤X，成立於下一根open按策略方向新增一口；低於X也仍用加X，不自動改成減X。'],['KBAR通過才查持倉保護；尚無移停線只固定損，有線才查直停優先及回撤。更新線以open換距離，close穿線也退，實際均open成交。','已持有天數每曆日末先>=設定就按open平，否則加一；資料末筆按close平。換約共用一口平開後continue。'],[cost,'每子項一口、ID全部1。換約未覆寫偏移函式，風控線保留舊約價，並非隨delta平移。'],['容量檢查使用有號old_pos<最大口數而非絕對值；選空時負部位可能永遠小於正上限，無法視為可靠空倉口數上限。','持有天數按曆日且退出用最後根open，不是等close成交；期間可多日重疊新增。','直接停利未啟移停前無效；移停只要求新線不同，可能向不利方向改。'],protect|{'幾天內漲跌':'以今日與N筆前日收盤作端點比較，不是N天振幅或逐日連漲跌。','上漲或下跌':'上漲看今日>=前收+距離，下跌看今日<=前收−距離，等號通過。','漲跌比':'以N筆前收盤換%或純點數的端點變動門檻。','隔日開盤':'高於X／低於X都與今日close+開盤X比較，使用>=／<=。','開盤X':'以今日收盤換%或點數並加到今日close，負值才是低於今日收盤的參考價。','最大口數':'程式只查有號淨量<此值；做多可限量，做空持負值時可能持續加空，非abs上限。'})
add('新低作多新高出','日低嚴格創M日新低後延遲P日新增多單，停損後可反彈重進，最終按新高延遲或共同持有計數全部退出。','新低反轉與新高退出',['每曆日末保存日K low/high，當日low嚴格低於前M日則更新新低索引；Count−索引恰等P且abs現倉未滿時，下一根open加一多。','子項停損後未達最多停損次數仍啟動，後續KBAR取樣open>=其前次進場價可再買一口，重新設損線。'],['持多且KBAR通過，open<=入場−損距離就open平，已停損加一；達上限時停止移除該子項。','新高出場：持倉時若日high嚴格高於前M日則更新新高索引，延遲恰P時下一open停止所有子項。固定天數：全體共用pday累計到恰M，下一open全停並清pday。','資料末筆close平持倉；換約一口平開後continue，未覆寫偏移，損線與重進參考保留舊約價。'],[cost,'新低日期只在舊倉未滿時更新；新高與pday只在本根處理完舊項的old_pos>0時計。新項先建立再查全平，新項可同一下一open買又平。','新低／新高當天Count−索引為1，P=1即下一根成交；固定pday是整體計數，非每子項自己的持有天數。'],['重進容量使用反序掃描已累計的部分old_pos，尚未納入後續子項，可能超出整體最多口數。','所有倉因停損變空手不會自動清pday，因此固定天數可跨不同持有段累積；只有恰等判斷而非>=。','日K精確日期不存在會直接負索引；新低暖機不足的continue也會略過同根後面的新高／固定天數退出判斷。'],{'突破M日低點':'日low嚴格小於前M筆low才新低，相等不算。只在舊持倉未滿時更新新低索引。','新低後P日進場':'樣本Count−最新新低索引恰等此數，突破當天為1；P=1在其後下一根open進。','最多口數':'日界新增用abs總持倉檢查；逐子項重進卻只看反序掃過的部分累計，不能保證所有路徑不超量。','出場機制':'新高出場依日high新高延遲；固定天數按所有子項共同pday計，條件成立把啟動項全停止。','固定M日出場':'持倉日界共同pday加一並恰等此數才全平，非逐筆計天；只有固定退出時清計數。','突破M日高點':'持倉時今日high嚴格大於前M筆high才更新新高索引。','新高後P日出場':'Count−最新新高索引恰等此數，突破當天為1，成立下一根open全平。','停損':'每次新／再進場價減%或點數，不Round；取樣open<=就實際open退。換約不偏移此線。','最多停損次數':'每子項停損後計數>=此數停止；未達可回前次進場價重進。0不阻止初次買入，但首次停損會停止。','KBAR間隔ex':'逐子項停損與反彈重進依分鐘相位；日界新低進、新高全出、固定天數及末筆不受此篩選。','開始交易時間':'ValidKBAR分鐘相位起點，不是日界新低買進前的硬截止。'})
(S/'analysis/SuperDaily.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote Daily opening/black/balloon/newlowhigh')
